WITH web_events_by_session AS (SELECT session_id, SUM(duration_sec) AS total_duration_sec, SORT_ARRAY(COLLECT_SET(page)) AS page_list FROM web_events WHERE event_type IN ('add_to_cart', 'search', 'page_view') GROUP BY session_id) SELECT sessions.id, sessions.browser, web_events_by_session.total_duration_sec, web_events_by_session.page_list FROM sessions JOIN web_events_by_session ON sessions.id = web_events_by_session.session_id ORDER BY id DESC;
